{
  "description": "A large upright bird-like creature is shown in right-facing profile standing on a small patch of ground with sparse grass and tiny purple and yellow flowers. It has a stout, ovoid body held vertically, with a rounded black head bearing a long slender dark beak and a small dark eye, a bright yellow to orange patch on the side of the neck behind the head, a white and pale yellow chest and belly with dense short shaggy plumage, and a thick covering of brown velvety-fuzzy plumage over the back, sides and the single visible flipper-like wing held against its side. The lower rear bears a short stiff black tail of pointed feathers, and the body is supported by two short thick scaly legs ending in large clawed feet resting on the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "rounded and glossy black on the crown, face and throat with a small dark eye on the side and a long slender dark gray-black beak tapering to a slightly down-hooked tip pointing to the right; a bright yellow-orange patch covers the side of the neck immediately behind the black face",
      "where": "at the top right of the body, atop the neck"
    },
    {
      "part": "legs",
      "looks_like": "short, thick and columnar, covered in wrinkled scaly gray-brown skin",
      "where": "extending down from the lower belly to the ground, under the center of the body"
    },
    {
      "part": "feet",
      "looks_like": "large flat scaly gray-brown feet with three forward-pointing toes each tipped with a dark curved claw, the skin wrinkled and textured",
      "where": "at the bottom of each leg, resting on the ground patch"
    },
    {
      "part": "wings",
      "looks_like": "one flipper-like wing visible, long and narrow with dense brown fuzzy plumage and a thin pale cream edge along the trailing margin, the tip rounded",
      "where": "on the side of the body, attached at the shoulder and lying close against the torso from upper back to mid-body"
    },
    {
      "part": "tail",
      "looks_like": "short, stiff and pointed, composed of narrow black feathers with a slightly ragged, layered tip",
      "where": "projecting from the lower rear of the body to the left, just above the ground"
    },
    {
      "part": "feathers",
      "looks_like": "dense short plumage: white and shaggy on the chest and belly with a yellow wash on the upper chest, brown and velvety-fuzzy on the back and outer wing, glossy black on the head and tail",
      "where": "covering the entire body except the beak, legs and feet"
    },
    {
      "part": "markings",
      "looks_like": "a distinct bright yellow-orange auricular patch behind the eye and black face, a thin black stripe separating the brown dorsum from the white chest, and a sharp contrast between the white ventral plumage and brown dorsal plumage",
      "where": "on the side of the neck and along the side of the torso"
    }
  ],
  "attached_objects": [],
  "animals": [
    "penguin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 1,
  "extra_limb_pieces": 0,
  "tails": 1
}
